select 'rebalance' k, type, left(member_id,12) mem, generation_id gen, partitions, occurred_at from rebalance_event where occurred_at between @ts - interval 5 second and @ts + interval 60 second order by id;
select 'exec-by-result' k, j.type, e.result, count(*) n, round(sum(timestampdiff(microsecond,e.received_at,e.finished_at))/1e6,1) total_sec from worker_execution e join processing_job j on j.id=e.job_id where e.received_at>=@t0 and e.received_at<@te group by j.type, e.result order by j.type, e.result;
select 'redelivered' k, e.partition_no p, e.record_offset o, e.job_id, j.type, left(e.member_id,12) mem, e.generation_id gen, e.result, e.received_at, e.finished_at, round(timestampdiff(microsecond,e.received_at,e.finished_at)/1e6,1) sec from worker_execution e join processing_job j on j.id=e.job_id where e.received_at>=@t0 and e.received_at<@te and (e.partition_no, e.record_offset) in (select partition_no, record_offset from worker_execution where received_at>=@t0 and received_at<@te group by partition_no, record_offset having count(*)>1) order by e.partition_no, e.record_offset, e.id;
select 'jobs' k, status, count(*) from processing_job where video_id>=@first group by status;
